import json, numpy as np

src='/gpfs/kjhan/CF4/q1_z0_selection_sensitivity_v1/posterior_sensitivity.npz'; tr='/gpfs/kjhan/CF4/recon/linear_cr/v3_bgc_lg_peak_grafic_p3429_s5108_n576/transfer_p3429_s5108_n576.npz'; f=np.load(src); low=f['v2_mean'].astype(np.float64); n=low.shape[0]; box=384.; k0=2*np.pi/box; k=np.meshgrid(*([np.fft.fftfreq(n)*n*k0]*3),indexing='ij'); km=np.sqrt(sum(x*x for x in k)); kcut=.30; rng=np.random.default_rng(20261007); lk=np.fft.fftn(low); p_low=np.abs(lk)**2/n**6; sel=(km>=kcut*.8)&(km<=kcut*1.2)&(p_low>0); amp=float(np.median(p_low[sel])) if np.any(sel) else 1.; tf=np.load(tr); tk=np.asarray(tf['kphys']); tv=np.asarray(tf['T']); target=np.interp(np.maximum(km,tk[0]),tk,tv,left=tv[0],right=tv[-1])**2*np.maximum(km,tk[0])**0.96; target*=amp/(np.median(target[sel]) if np.any(sel) else 1.); noise=rng.normal(size=(n,n,n)); nk=np.fft.fftn(noise); highk=nk*np.sqrt(n**6*np.maximum(target,0.)/(np.mean(np.abs(nk[km>=kcut])**2)+1e-30)); w=np.clip((km-(kcut-.05))/.10,0.,1.); w=w*w*(3.-2.*w); outk=(1.-w)*lk+w*highk; out=np.fft.ifftn(outk).real; out-=out.mean(); np.savez_compressed('/gpfs/kjhan/CF4/q1_low_highk_blend_dev_v1.npz',field=out,low_k_cut=kcut,taper_width=.10)
print(json.dumps({'status':'LOW_HIGHK_BLEND_DEVELOPMENT','grid':n,'box_cMpc_h':box,'kcut_h_Mpc':kcut,'mean':float(out.mean()),'finite':bool(np.all(np.isfinite(out))),'low_modes_preserved_fraction':float(np.sum(np.abs(outk[w==0]-lk[w==0])**2)/(np.sum(np.abs(lk[w==0])**2)+1e-30))}),flush=True)
